#!/bin/bash
# =============================================================================
# SRW3 Phase 1V — compatibility wrapper for the Phase 1U model runner.
# (phase1v/tests/run_1u_model_tests_compat.sh)
#
# Workstream B4: the documented Phase 1U command
#       bash phase1u/tests/run_1u_model_tests.sh
# depended on leftover filesystem state that a clean checkout does not have:
#     /tmp/p1u-old-harness/            (the old-harness directory)
#     /tmp/p1u-old-harness/srw3.k      (copy made by the 1U runner itself)
#     /tmp/p1u-old-harness/t1_harness_old.k  (NEVER generated by the 1U
#                                      runner — a leftover from the 1U
#                                      session; B1 finding of record)
# and on a toolchain env file that may sit at either of the two recorded
# locations (tools/ pre-reset, tools1v/ post-reset).
#
# This wrapper makes the EXACT documented command self-contained: it
# provisions the missing old-harness input FROM COMMITTED REPOSITORY OBJECTS
# (the pinned 1T-tip model + the committed harness source with ONE
# documented transformation: the relative require "../../k/srw3.k" is
# rewritten to "srw3.k" because the wrapper materializes the old model as
# the harness's sibling — the transformation the 1U runner silently
# assumed), puts the pinned toolchain on PATH, and then execs the ORIGINAL
# runner unmodified. The original script itself is NOT edited (it is the
# Phase 1U evidence of record).
#
# The preferred Phase 1V runner is phase1v/tests/run_1v_model_tests.sh,
# which needs no wrapper (it generates every input itself and asserts
# outcomes). This wrapper exists ONLY so the historical documented
# invocation reproduces from a clean checkout.
# =============================================================================
set -u
cd "$(dirname "$0")/../.." || exit 1
REPO=$PWD

# --- toolchain on PATH before the original runner runs (its `source` of the
# OLD tools/env.sh path is allowed to fail silently; the runner uses `set -u`
# without set -e, and PATH is already correct by then) ------------------------
if [ -n "${KTOOLS:-}" ] && [ -f "$KTOOLS/env.sh" ]; then source "$KTOOLS/env.sh"
elif [ -f /home/z/my-project/tools1v/env.sh ]; then source /home/z/my-project/tools1v/env.sh
elif [ -f /home/z/my-project/tools/env.sh ]; then source /home/z/my-project/tools/env.sh
else echo "[1U-COMPAT] FATAL: pinned toolchain env.sh not found (set KTOOLS=)"; exit 2; fi

OLDH=/tmp/p1u-old-harness
echo "[1U-COMPAT] provisioning $OLDH from committed repository objects"
mkdir -p "$OLDH"

# 1. the pinned 1T-tip model (exactly what the 1U runner regenerates itself)
git -C "$REPO" show 2247e68872d7a5f8bd8920db96db3ace290535b2:k/srw3.k > /tmp/p1u-old-srw3.k || exit 3
cp /tmp/p1u-old-srw3.k "$OLDH/srw3.k"

# 2. the old T1 harness: the COMMITTED Phase 1U harness source with ONE
#    documented transformation — the require path "../../k/srw3.k" (repo
#    layout) becomes "srw3.k" (sibling layout). Every other byte identical.
git -C "$REPO" show 8697bd744faee0b17156393fd8f57dd87e51598e:phase1u/tests/t1_harness.k \
  | sed 's|requires "\.\./\.\./k/srw3\.k"|requires "srw3.k"|' > "$OLDH/t1_harness_old.k" || exit 3

# 3. assert the transformation is EXACTLY the intended one: exactly one line
#    differs from the committed source, and it is the require line.
if ! git -C "$REPO" show 8697bd744faee0b17156393fd8f57dd87e51598e:phase1u/tests/t1_harness.k \
     | diff - "$OLDH/t1_harness_old.k" > /tmp/p1u-harness-transform.diff 2>&1; then
  LINES=$(wc -l < /tmp/p1u-harness-transform.diff)
  if [ "$LINES" -gt 8 ]; then
    echo "[1U-COMPAT] FATAL: harness transformation touched more than the require line (diff $LINES lines)"; exit 4
  fi
  grep -q '^[<>] requires' /tmp/p1u-harness-transform.diff || { echo "[1U-COMPAT] FATAL: transformed line is not the require line"; exit 4; }
fi
echo "[1U-COMPAT] harness transformation verified: only the require path differs"

echo "[1U-COMPAT] exec: bash phase1u/tests/run_1u_model_tests.sh $*"
exec bash "$REPO/phase1u/tests/run_1u_model_tests.sh" "$@"
